1436.     pub open spec fn init(self) -> StatePred<ClusterState> {
1437.         |s: ClusterState| {
1438.             // The API server is initialized...
1439.             &&& (api_server(self.installed_types).init)(s.api_server)
1440.             // and the built-in controllers are initialized...
1441.             &&& (builtin_controllers().init)(())
1442.             // and the network is initialized...
1443.             &&& (network().init)(s.network)
1444.             // and message drop is enabled...
1445.             &&& s.req_drop_enabled
1446.             // and pod monkey is enabled...
1447.             &&& s.pod_monkey_enabled
1448.             // and for each controller...
1449.             &&& forall |key| #[trigger] self.controller_models.contains_key(key)
1450.                 ==> {
1451.                     let model = self.controller_models[key];
1452.                     // its internal state exists...
1453.                     &&& s.controller_and_externals.contains_key(key)
1454.                     // and is initialized...
1455.                     &&& (controller(model.reconcile_model, key).init)(s.controller_and_externals[key].controller)
1456.                     // and crash for this controller is enabled...
1457.                     &&& s.controller_and_externals[key].crash_enabled
1458.                     // and if the controller has an associated external system...
1459.                     &&& model.external_model is Some
1460.                         ==> {
1461.                             // the internal state of that external system exists...
1462.                             &&& s.controller_and_externals[key].external is Some
1463.                             // and is initialized.
1464.                             &&& (external(model.external_model->0).init)(s.controller_and_externals[key].external->0)
1465.                         }
1466.                 }
1467.         }
1468.     }
